      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n11/24~25) 1시간 40만) 20세 이상 ~ 남성) 푸드 크리에이터 온라인 화상 인터뷰\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.09. 13:06\n조회 13\n구독\n11/24~25) 1시간 40만) 20세 이상 ~ 남녀) 푸드 크리에이터 온라인 화상 인터뷰\n신청하신분은 재신청 안하셔도 됩니다 ~\n장소: 인터넷이 안정적이면서 조용한곳 (예: 자택 등)\n1시간 진행 일대일 온라인 화상인터뷰 : 11월 24일(화) ~25일 (수) 중 하루 60분간 인터뷰 /시간은 확정시 안내드립니다\n사전과제는 본인에 대한 간단한 소개 1~2분 영상찍기\n사례비 : 40만원\n적어주실 내용: 이름 /연락처 /성별/나이/ 링크 계정/ 팔로우 수\n푸드 크래프트 전문 크리에이터 (최우선 타깃):\n아이스크림, 프리미엄 초콜릿, 파티세리/베이커리, 디저트 전문 크리에이터\n라이프스타일 & 일반 푸드 크리에이터:\n미식, 홈카페, 감각적인 식문화를 다루는 푸드/라이프스타일 인플루언서\n인접 감각 카테고리 크리에이터 (Adjacent Categories):\n뷰티, 향수(프래그런스), 패션, 디자인 분야 등 '감각적(Sensory) 시각'을 지닌 크리에이터\n선발 이유: 음식 외부 영역에서 '장인정신(Craft)'과 '욕망/소장 가치(Desire)'에 대한 신선하고 세련된 어휘와 인사이트를 제시할 수 있는 인물\n팔로워 규모: 1만(10k) ~ 5만(150k) 범위 내 마이크로/매크로 인플루언서\n너무 대형 셀럽보다는 본인의 채널과 팔로워 관여도가 끈끈한 크리에이터가 적합합니다.\n팔로워 위치: 오디언스(구독자/팔로워)의 대다수가 국내(대한민국) 기반이어야 함.\n활동성: 현재 활발히 운영 중인 계정 (최근 3개월간 최소 주 1회 이상 정기적인 피드/콘텐츠 업로드 필수).\n주요 플랫폼: 인스타그램(Instagram) 또는 유튜브(YouTube) 중심 (틱톡, 네이버 인플루언서 블로그 가능).\n카테고리 태도: 평소 프리미엄 아이스크림을 정기적으로 소비하며, 하겐다즈 브랜드에 대해 거부감이 없어야 함\n음식의 감각적 경험(맛, 향, 식감, 비주얼, 소리 등)을 섬세하고 생생하게 표현하는 인물\n풍부한 감각적 어휘를 구사하여, 설명만 들어도 대상이 탐나고 먹고 싶어지게 만드는 전달력을 가진 인물\n디저트/미식을 죄책감(Guilt)이나 과식(Excess)으로 대하지 않고, 자신을 위한 세련되고 가치 있는 즐거움(Considered Pleasure)으로 여기는 인물\n제품 이면의 스토리, 원재료의 산지(Provenance), 만드는 장인/셰프, 정교한 제조 기술에 진심 어린 관심을 기울이는 인물\nhttps://forms.gle/kBHjKCyTzbS6YBnt9\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n11/24~25) 1시간 40만) 20세 이상 ~ 여성) 푸드 크리에이터 온라인 화상 인터뷰\n좌담회알바좌담회카페\n26.11.09.\n댓글\n0\n11/24~25) 1시간 40만) 20세 이상 ~ 남성) 푸드 크리에이터 온라인 화상 인터뷰\n좌담회알바좌담회카페\n26.11.09.\n댓글\n0\n급급급) 60분 줌 온라인 조사 20만원)구독 고객 대상 AS 직접 수행(엔지니어)\n좌담회알바좌담회카페\n26.11.09.\n댓글\n0\n급급급) 60분 줌 온라인 조사 20만원)정기 방문케어 (케어 매니저) 경험자\n좌담회알바좌담회카페\n26.11.09.\n댓글\n0\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
