      "title": "고유링크)실링팬 관련 설문조사-최근 3년이내 실링팬 설치 경험자(150명) 30~39세 여성",
      "source": "naver_cafe",
      "source_url": "https://m.cafe.naver.com/togetheralba/130924",
      "target_age": "",
      "target_gender": "",
      "target_condition": "설문조사입니다.",
      "date": "추후 안내드립니다",
      "time": "",
      "duration": "",
      "reward": "",
